  --void: #07060e;
  --void-2: #100e18;
  --paper: #f4ead2;
  --paper-dim: #c9b896;
  --gold: #e0b050;
  --gold-dim: #8a6a28;
  --ember: #ff6a2a;
  --ice: #7ee7ff;
  --null: #ff2d6a;
  --ok: #9dffb0;
  --violet: #b48cff;
  --shadow: 0 20px 80px rgba(0, 0, 0, 0.55);
  font-synthesis: none;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body, #app {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--void);
  color: var(--paper);
  font-family: Outfit, "Segoe UI", sans-serif;
  font-weight: 400;
  user-select: none;
}

canvas#c {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

#grade {
  pointer-events: none;
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 80% at 50% 20%, transparent 40%, rgba(7, 6, 14, 0.35) 100%),
    linear-gradient(180deg, rgba(40, 20, 60, 0.12), transparent 40%, rgba(10, 6, 20, 0.2));
  mix-blend-mode: multiply;
}

#vignette {
  pointer-events: none;
  position: absolute;
  inset: 0;
  box-shadow: inset 0 0 180px 40px rgba(0, 0, 0, 0.55);
}

#flash {
  pointer-events: none;
  position: absolute;
  inset: 0;
  opacity: 0;
  background: #fff6e0;
  mix-blend-mode: overlay;
}

#float-layer {
  pointer-events: none;
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.floater {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  font-size: 22px;
  letter-spacing: 0.04em;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.8);
  animation: floatUp 0.7s ease-out forwards;
  white-space: nowrap;
}
.floater.crit { font-size: 28px; color: var(--gold); }
.floater.heal { color: var(--ok); }
.floater.sy { color: var(--ice); font-style: italic; }

@keyframes floatUp {
  0% { opacity: 1; transform: translate(-50%, -50%) scale(0.7); }
  20% { transform: translate(-50%, -70%) scale(1.08); }
  100% { opacity: 0; transform: translate(-50%, -160%) scale(1); }
}

#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 22px 28px 20px;
}

.hud-top, .hud-bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.hud-top { align-items: flex-start; }

.hud-kicker, .overlay-kicker {
  font-size: 11px;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 500;
}

.hud-chamber {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 28px;
  font-weight: 600;
  line-height: 1.1;
  margin-top: 2px;
}

.hud-run { display: flex; gap: 18px; }
.hud-stat { text-align: right; }
.hud-stat span {
  display: block;
  font-size: 10px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--paper-dim);
}
.hud-stat b {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 26px;
  font-weight: 600;
}

.syzygy-banner {
  position: absolute;
  left: 50%;
  top: 18%;
  transform: translateX(-50%);
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 54px;
  letter-spacing: 0.42em;
  font-weight: 600;
  color: var(--paper);
  text-shadow: 0 0 40px rgba(224, 176, 80, 0.55);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}
.syzygy-banner.on {
  animation: syFlash 0.85s ease-out;
}
@keyframes syFlash {
  0% { opacity: 0; letter-spacing: 0.7em; transform: translateX(-50%) scale(0.92); }
  18% { opacity: 1; letter-spacing: 0.42em; transform: translateX(-50%) scale(1); }
  100% { opacity: 0; }
}

.integrity { display: flex; gap: 7px; align-items: center; }
.pip {
  width: 16px;
  height: 16px;
  border: 1px solid var(--gold);
  transform: rotate(45deg);
  background: transparent;
  box-shadow: 0 0 10px rgba(224, 176, 80, 0.15);
}
.pip.on {
  background: var(--paper);
  box-shadow: 0 0 14px rgba(244, 234, 210, 0.55);
}
.pip.half {
  background: linear-gradient(135deg, var(--paper) 50%, transparent 50%);
}

.orrery {
  display: flex;
  gap: 8px;
  align-items: center;
  min-height: 42px;
}
.orb-slot {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(224, 176, 80, 0.35);
  display: grid;
  place-items: center;
  position: relative;
  background: rgba(8, 6, 16, 0.45);
}
.orb-slot i {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  display: block;
  box-shadow: 0 0 10px currentColor;
}
.orb-slot.sel { border-color: var(--paper); box-shadow: 0 0 0 1px var(--paper); }
.orb-slot.away { opacity: 0.4; }
.orb-slot.empty { opacity: 0.25; }

.cooldowns { display: flex; gap: 10px; }
.cd {
  width: 72px;
  height: 6px;
  background: rgba(255, 255, 255, 0.08);
  position: relative;
  overflow: hidden;
}
.cd i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  background: var(--gold);
  transform-origin: left;
}
.cd label {
  position: absolute;
  top: 10px;
  left: 0;
  font-size: 9px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--paper-dim);
}

.hint {
  position: absolute;
  left: 50%;
  bottom: 92px;
  transform: translateX(-50%);
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--paper-dim);
  text-align: center;
  max-width: 640px;
  text-shadow: 0 2px 16px #000;
  transition: opacity 0.4s;
}

.boss-bar {
  position: absolute;
  left: 50%;
  top: 72px;
  transform: translateX(-50%);
  width: min(520px, 70vw);
  text-align: center;
}
.boss-name {
  font-family: "Cormorant Garamond", Georgia, serif;
  letter-spacing: 0.28em;
  font-size: 15px;
  margin-bottom: 8px;
  color: var(--null);
}
.boss-track {
  height: 4px;
  background: rgba(255, 45, 106, 0.15);
  border: 1px solid rgba(255, 45, 106, 0.4);
}
.boss-track i {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--null);
  box-shadow: 0 0 12px var(--null);
  transform-origin: left;
}

.announce {
  pointer-events: none;
  position: absolute;
  left: 50%;
  top: 36%;
  transform: translate(-50%, -50%);
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 40px;
  letter-spacing: 0.22em;
  opacity: 0;
  text-align: center;
  text-shadow: 0 8px 40px #000;
}
.announce.on { animation: announce 1.6s ease-out; }
@keyframes announce {
  0% { opacity: 0; transform: translate(-50%, -40%); }
  15% { opacity: 1; transform: translate(-50%, -50%); }
  75% { opacity: 1; }
  100% { opacity: 0; }
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(7, 6, 14, 0.55);
  backdrop-filter: blur(8px);
  z-index: 5;
  padding: 40px 24px;
  text-align: center;
}
.title-overlay {
  background: linear-gradient(180deg, rgba(7, 6, 14, 0.15) 0%, rgba(7, 6, 14, 0.72) 70%);
  backdrop-filter: none;
}
.overlay.hidden, .hidden { display: none !important; }

.overlay-title, h1 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
}

h1 {
  font-size: clamp(72px, 14vw, 148px);
  letter-spacing: 0.28em;
  line-height: 0.9;
  margin: 10px 0 8px 12px;
  text-shadow: 0 0 80px rgba(224, 176, 80, 0.25);
}

.overlay-title { font-size: 52px; letter-spacing: 0.12em; margin: 8px 0 12px; }

.title-mark, .overlay-kicker {
  letter-spacing: 0.42em;
  font-size: 11px;
  color: var(--gold);
}

.title-tag {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-style: italic;
  font-size: 22px;
  color: var(--paper-dim);
  margin-bottom: 28px;
}

.title-actions, .pause-actions { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }

.title-meta {
  margin-top: 36px;
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--paper-dim);
}

.btn {
  pointer-events: auto;
  appearance: none;
  border: 1px solid rgba(244, 234, 210, 0.28);
  background: rgba(8, 6, 16, 0.5);
  color: var(--paper);
  font-family: Outfit, sans-serif;
  font-size: 12px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  padding: 14px 22px;
  cursor: pointer;
  transition: 0.18s ease;
}
.btn:hover { border-color: var(--paper); background: rgba(255, 255, 255, 0.06); }
.btn.gold {
  border-color: var(--gold);
  color: var(--void);
  background: var(--gold);
}
.btn.gold:hover { background: var(--paper); }
.btn.ghost { background: transparent; margin-top: 18px; }
.btn:disabled { opacity: 0.35; cursor: not-allowed; }

.panel {
  background: rgba(10, 8, 18, 0.86);
  border: 1px solid rgba(224, 176, 80, 0.22);
  box-shadow: var(--shadow);
  padding: 36px 40px 32px;
  max-width: 760px;
  width: 100%;
}
.panel.wide { max-width: 920px; }
.panel.slim { max-width: 420px; }

.overlay-lead {
  color: var(--paper-dim);
  font-size: 15px;
  line-height: 1.55;
  margin: 0 auto 22px;
  max-width: 52ch;
}

.how-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  text-align: left;
  margin: 18px 0 24px;
}
.how-grid h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 22px;
  margin-bottom: 6px;
  color: var(--gold);
}
.how-grid p { font-size: 13px; line-height: 1.5; color: var(--paper-dim); }
.how-grid em { color: var(--paper); font-style: normal; }

.keys {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px 12px;
  text-align: left;
  margin-bottom: 22px;
}
.keys div { display: flex; gap: 8px; align-items: baseline; }
.keys dt {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  min-width: 52px;
}
.keys dd { font-size: 13px; color: var(--paper-dim); }

.card-row {
  display: flex;
