  justify-content: center;
  flex-wrap: wrap;
  margin: 10px 0 8px;
  pointer-events: auto;
}
.card {
  width: 230px;
  min-height: 280px;
  text-align: left;
  padding: 22px 20px 20px;
  background: linear-gradient(180deg, rgba(28, 20, 40, 0.95), rgba(10, 8, 18, 0.95));
