const texCache = new Map()

export function glowTexture(hex = '#ffffff', size = 128) {
  const key = hex + size
  if (texCache.has(key)) return texCache.get(key)
  const c = document.createElement('canvas')
  c.width = c.height = size
  const g = c.getContext('2d')
  const grd = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  grd.addColorStop(0, hex)
  grd.addColorStop(0.22, hex)
  grd.addColorStop(0.55, hex + '88')
  grd.addColorStop(1, 'rgba(0,0,0,0)')
  g.fillStyle = grd
  g.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  texCache.set(key, tex)
  return tex
}

export function nebulaTexture() {
  const size = 256
  const c = document.createElement('canvas')
  c.width = c.height = size
  const g = c.getContext('2d')
  g.clearRect(0, 0, size, size)
  for (let i = 0; i < 8; i++) {
    const x = size * (0.2 + Math.random() * 0.6)
    const y = size * (0.2 + Math.random() * 0.6)
    const r = size * (0.18 + Math.random() * 0.28)
    const grd = g.createRadialGradient(x, y, 0, x, y, r)
    const hue = 250 + Math.random() * 80
    grd.addColorStop(0, `hsla(${hue}, 60%, 55%, 0.28)`)
    grd.addColorStop(1, 'rgba(0,0,0,0)')
    g.fillStyle = grd
    g.fillRect(0, 0, size, size)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function makeGlowSprite(color, scale = 2.4) {
  const hex = '#' + new THREE.Color(color).getHexString()
  const mat = new THREE.SpriteMaterial({
    map: glowTexture(hex),
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    opacity: 0.9,
  })
  const s = new THREE.Sprite(mat)
  s.scale.setScalar(scale)
  return s
}

export class Trail {
  constructor(scene, color, max = 48, width = 0.12) {
    this.max = max
    this.pts = []
    this.geom = new THREE.BufferGeometry()
    const pos = new Float32Array(max * 3)
    const cols = new Float32Array(max * 4)
    this.geom.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    this.geom.setAttribute('color', new THREE.BufferAttribute(cols, 4))
    this.mat = new THREE.LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    this.line = new THREE.Line(this.geom, this.mat)
    this.line.frustumCulled = false
    this.color = new THREE.Color(color)
    this.width = width
    scene.add(this.line)
  }

  push(x, y, z) {
    this.pts.push(x, y, z)
    if (this.pts.length > this.max * 3) this.pts.splice(0, 3)
    const pos = this.geom.attributes.position
    const col = this.geom.attributes.color
    const n = this.pts.length / 3
    for (let i = 0; i < this.max; i++) {
      const src = Math.min(i, n - 1)
      pos.setXYZ(i, this.pts[src * 3] || 0, this.pts[src * 3 + 1] || 0, this.pts[src * 3 + 2] || 0)
      const a = n < 2 ? 0 : (i / Math.max(1, n - 1)) * 0.85
      col.setXYZW(i, this.color.r, this.color.g, this.color.b, i < n ? a : 0)
    }
    this.geom.setDrawRange(0, Math.max(2, n))
    pos.needsUpdate = true
    col.needsUpdate = true
  }

  setColor(c) {
    this.color.set(c)
  }

  clear() {
    this.pts.length = 0
  }

  dispose(scene) {
    scene.remove(this.line)
    this.geom.dispose()
    this.mat.dispose()
  }
}

export class Particles {
  constructor(scene, cap = 500) {
    this.cap = cap
    this.list = []
    this.geom = new THREE.BufferGeometry()
    this.pos = new Float32Array(cap * 3)
    this.col = new Float32Array(cap * 3)
    this.sizes = new Float32Array(cap)
    this.geom.setAttribute('position', new THREE.BufferAttribute(this.pos, 3))
    this.geom.setAttribute('color', new THREE.BufferAttribute(this.col, 3))
    this.geom.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1))
    this.mat = new THREE.PointsMaterial({
      size: 0.18,
      vertexColors: true,
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
      map: glowTexture('#ffffff', 64),
      alphaMap: glowTexture('#ffffff', 64),
    })
    this.points = new THREE.Points(this.geom, this.mat)
    this.points.frustumCulled = false
    scene.add(this.points)
  }

  burst(x, y, z, color, n = 14, speed = 6, life = 0.5, size = 0.22) {
    const c = new THREE.Color(color)
    for (let i = 0; i < n; i++) {
      if (this.list.length >= this.cap) this.list.shift()
      const th = Math.random() * Math.PI * 2
      const ph = Math.acos(2 * Math.random() - 1)
      const s = speed * (0.3 + Math.random())
      this.list.push({
        x,
        y,
        z,
        vx: Math.sin(ph) * Math.cos(th) * s,
        vy: Math.cos(ph) * s * 0.6 + 1.4,
        vz: Math.sin(ph) * Math.sin(th) * s,
        life,
        max: life,
        r: c.r,
        g: c.g,
        b: c.b,
        size,
      })
    }
  }

  ring(x, y, z, color, n = 24, speed = 8) {
    const c = new THREE.Color(color)
    for (let i = 0; i < n; i++) {
      if (this.list.length >= this.cap) this.list.shift()
      const a = (i / n) * Math.PI * 2
      this.list.push({
        x,
        y,
        z,
        vx: Math.cos(a) * speed,
        vy: 0.4,
        vz: Math.sin(a) * speed,
        life: 0.45,
        max: 0.45,
        r: c.r,
        g: c.g,
        b: c.b,
        size: 0.2,
      })
    }
  }

  update(dt) {
    const g = 6
    for (let i = this.list.length - 1; i >= 0; i--) {
      const p = this.list[i]
      p.life -= dt
      if (p.life <= 0) {
        this.list.splice(i, 1)
        continue
      }
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.z += p.vz * dt
      p.vy -= g * dt
      p.vx *= 0.98
      p.vz *= 0.98
    }
    for (let i = 0; i < this.cap; i++) {
      const p = this.list[i]
      if (!p) {
        this.pos[i * 3] = 0
        this.pos[i * 3 + 1] = -99
        this.pos[i * 3 + 2] = 0
        this.sizes[i] = 0
        continue
      }
      this.pos[i * 3] = p.x
      this.pos[i * 3 + 1] = p.y
      this.pos[i * 3 + 2] = p.z
      const a = p.life / p.max
      this.col[i * 3] = p.r
      this.col[i * 3 + 1] = p.g
      this.col[i * 3 + 2] = p.b
      this.sizes[i] = p.size * (0.4 + a)
    }
    this.geom.attributes.position.needsUpdate = true
    this.geom.attributes.color.needsUpdate = true
    this.geom.attributes.size.needsUpdate = true
    this.geom.setDrawRange(0, this.cap)
  }
}

export class CameraRig {
  constructor(camera) {
    this.camera = camera
    this.trauma = 0
    this.look = new THREE.Vector3()
    this.pos = new THREE.Vector3(0, 26, 20)
    this.kick = new THREE.Vector3()
  }

  shake(amt) {
    this.trauma = Math.min(1, this.trauma + amt)
  }

  update(dt, target, playing) {
    this.trauma = Math.max(0, this.trauma - dt * 1.8)
    const s = this.trauma * this.trauma
    const ox = (Math.random() * 2 - 1) * s * 0.55
    const oy = (Math.random() * 2 - 1) * s * 0.35
    const oz = (Math.random() * 2 - 1) * s * 0.55
    const desired = playing
      ? new THREE.Vector3(target.x + ox, 24.5 + oy, target.z + 18.5 + oz)
      : new THREE.Vector3(Math.sin(performance.now() * 0.00012) * 6, 22, 20)
    this.pos.lerp(desired, 1 - Math.pow(0.001, dt))
    this.camera.position.copy(this.pos)
    this.look.lerp(
      playing ? new THREE.Vector3(target.x, 0.4, target.z) : new THREE.Vector3(0, 0.4, 0),
      1 - Math.pow(0.0008, dt),
    )
    this.camera.lookAt(this.look)
  }
}

export function hexShape(def, extra = {}) {
  let geom
  const r = def.radius
  switch (def.shape) {
    case 'octa':
      geom = new THREE.OctahedronGeometry(r * 1.15, 0)
      break
    case 'tetra':
      geom = new THREE.TetrahedronGeometry(r * 1.35, 0)
      break
    case 'dodeca':
      geom = new THREE.DodecahedronGeometry(r * 1.05, 0)
      break
    case 'ico':
      geom = new THREE.IcosahedronGeometry(r * 1.05, 0)
      break
    case 'cube':
      geom = new THREE.BoxGeometry(r * 1.5, r * 1.5, r * 1.5)
      break
    case 'torus':
      geom = new THREE.TorusGeometry(r * 0.85, r * 0.28, 8, 16)
      break
    case 'cone':
      geom = new THREE.ConeGeometry(r * 0.9, r * 2, 5)
      break
    case 'capsule':
      geom = new THREE.CapsuleGeometry(r * 0.55, r * 1.4, 4, 8)
      break
    case 'box':
      geom = new THREE.BoxGeometry(r * 1.6, r * 1.6, r * 1.6)
      break
    default:
      geom = new THREE.SphereGeometry(r, 16, 12)
  }
  const mat = new THREE.MeshStandardMaterial({
    color: def.color,
    emissive: def.color,
    emissiveIntensity: extra.emissive ?? 0.55,
    roughness: 0.35,
    metalness: 0.45,
    flatShading: true,
  })
  const mesh = new THREE.Mesh(geom, mat)
  if (def.edge != null) {
    const edges = new THREE.EdgesGeometry(geom)
    const line = new THREE.LineSegments(
      edges,
      new THREE.LineBasicMaterial({
        color: def.edge,
        transparent: true,
        opacity: 0.9,
      }),
    )
    mesh.add(line)
  }
  return mesh
}

export function worldToScreen(v, camera, canvas) {
  const p = v.clone().project(camera)
  return {
    x: (p.x * 0.5 + 0.5) * canvas.clientWidth,
    y: (-p.y * 0.5 + 0.5) * canvas.clientHeight,
  }
}
