const $ = (id) => document.getElementById(id)

export class UI {
  constructor() {
    this.els = {
      hud: $('hud'),
      floor: $('hud-floor'),
      chamber: $('hud-chamber'),
      ash: $('hud-ash'),
      align: $('hud-align'),
      integrity: $('integrity'),
      orrery: $('orrery'),
      hint: $('hint'),
      banner: $('syzygy-banner'),
      announce: $('announce'),
      boss: $('boss-bar'),
      bossName: $('boss-name'),
      bossFill: $('boss-fill'),
      cards: $('cards'),
      cardRow: $('card-row'),
      cardSub: $('card-sub'),
      altar: $('altar'),
      altarGrid: $('altar-grid'),
      title: $('title'),
      how: $('how'),
      reliquary: $('reliquary'),
      unlockGrid: $('unlock-grid'),
      ashBank: $('ash-bank'),
      titleMeta: $('title-meta'),
      pause: $('pause'),
      results: $('results'),
      resultsKicker: $('results-kicker'),
      resultsTitle: $('results-title'),
      resultsLead: $('results-lead'),
      resultsStats: $('results-stats'),
      resultsUnlocks: $('results-unlocks'),
      flash: $('flash'),
      cdDash: $('cd-dash').querySelector('i'),
      cdPulse: $('cd-pulse').querySelector('i'),
      cdFling: $('cd-fling').querySelector('i'),
    }
    this._bannerT = 0
  }

  show(el, on = true) {
    el.classList.toggle('hidden', !on)
  }

  setTitle(meta) {
    this.show(this.els.title, true)
    this.show(this.els.hud, false)
    this.show(this.els.cards, false)
    this.show(this.els.altar, false)
    this.show(this.els.pause, false)
    this.show(this.els.results, false)
    this.show(this.els.how, false)
    this.show(this.els.reliquary, false)
    this.els.titleMeta.textContent = `Ash ${meta.ash}   ·   Runs ${meta.runs}   ·   Best ${meta.best}   ·   Wins ${meta.wins}`
  }

  hideMenus() {
    this.show(this.els.title, false)
    this.show(this.els.how, false)
    this.show(this.els.reliquary, false)
    this.show(this.els.results, false)
    this.show(this.els.pause, false)
  }

  playHud() {
    this.hideMenus()
    this.show(this.els.hud, true)
    this.show(this.els.cards, false)
    this.show(this.els.altar, false)
  }

  flash(color = '#fff6e0', ms = 90) {
    const el = this.els.flash
    el.style.background = color
    el.style.opacity = '0.85'
    clearTimeout(this._ft)
    this._ft = setTimeout(() => {
      el.style.transition = 'opacity 0.25s'
      el.style.opacity = '0'
    }, ms)
  }

  announce(text) {
    const el = this.els.announce
    el.textContent = text
    el.classList.remove('on')
    void el.offsetWidth
    el.classList.add('on')
  }

  syzygy(word = 'SYZYGY') {
    const el = this.els.banner
    el.textContent = word
    el.classList.remove('on')
    void el.offsetWidth
    el.classList.add('on')
  }

  hint(text) {
    this.els.hint.textContent = text || ''
  }

  float(layer, x, y, text, cls = '') {
    const n = document.createElement('div')
    n.className = 'floater ' + cls
    n.textContent = text
    n.style.left = x + 'px'
    n.style.top = y + 'px'
    layer.appendChild(n)
    setTimeout(() => n.remove(), 720)
  }

  renderRun(game) {
    const p = game.player
    const floor = HEAVENS[game.floor] || HEAVENS[2]
    this.els.floor.textContent = floor.kicker
    this.els.chamber.textContent = game.roomKind === 'boss' ? floor.name : `Chamber ${game.chamber}`
    this.els.ash.textContent = String(game.stardust)
    this.els.align.textContent = '×' + game.alignMul.toFixed(game.alignMul % 1 ? 1 : 0)

    const max = p.maxHp
    const hp = p.hp
    const hold = this.els.integrity
    if (hold.childElementCount !== max) {
      hold.innerHTML = ''
      for (let i = 0; i < max; i++) {
        const pip = document.createElement('div')
        pip.className = 'pip'
        hold.appendChild(pip)
      }
    }
    ;[...hold.children].forEach((pip, i) => {
      pip.classList.toggle('on', hp >= i + 1)
      pip.classList.toggle('half', hp > i && hp < i + 1)
    })

    const orr = this.els.orrery
    const slots = game.rules.slots
    if (orr.childElementCount !== slots) {
      orr.innerHTML = ''
      for (let i = 0; i < slots; i++) {
        const s = document.createElement('div')
        s.className = 'orb-slot empty'
        s.innerHTML = '<i></i>'
        orr.appendChild(s)
      }
    }
    ;[...orr.children].forEach((slot, i) => {
      const o = game.orbiters[i]
      slot.classList.toggle('empty', !o)
      slot.classList.toggle('sel', i === game.selected)
      slot.classList.toggle('away', !!(o && o.mode !== 'orbit'))
      const ic = slot.querySelector('i')
      if (o) {
        ic.style.background = o.def.glow
        ic.style.color = o.def.glow
        ic.style.display = 'block'
      } else ic.style.display = 'none'
    })

    const dash = game.dashCd <= 0 && game.dashCharges > 0 ? 1 : 1 - game.dashCd / game.dashMax
    const pulse = 1 - game.pulseCd / game.rules.pulseCd
    const fling = 1 - game.flingCd / 0.22
    this.els.cdDash.style.transform = `scaleX(${Math.max(0, Math.min(1, dash))})`
    this.els.cdPulse.style.transform = `scaleX(${Math.max(0, Math.min(1, pulse))})`
    this.els.cdFling.style.transform = `scaleX(${Math.max(0, Math.min(1, fling))})`

    if (game.boss) {
      this.show(this.els.boss, true)
      this.els.bossName.textContent = game.boss.title || game.boss.name
      const t = Math.max(0, game.boss.hp / game.boss.maxHp)
      this.els.bossFill.style.transform = `scaleX(${t})`
    } else this.show(this.els.boss, false)
  }

  showCards(choices, onPick) {
    this.show(this.els.cards, true)
    this.els.cardRow.innerHTML = ''
    choices.forEach((ed) => {
      const el = document.createElement('button')
      el.className = 'card ' + ed.rarity
      el.innerHTML = `<div class="rarity">${ed.rarity}</div><h3>${ed.name}</h3><p>${ed.desc}</p><div class="tag">${ed.tag}</div>`
      el.addEventListener('click', () => onPick(ed))
      this.els.cardRow.appendChild(el)
    })
  }

  hideCards() {
    this.show(this.els.cards, false)
  }

  showAltar(items, dust, onPick, onLeave) {
    this.show(this.els.altar, true)
    this.els.altarGrid.innerHTML = ''
    items.forEach((it) => {
      const el = document.createElement('button')
      el.className = 'shop-item'
      const afford = dust >= it.cost || it.kind === 'blood'
      el.disabled = !afford && it.kind !== 'blood'
      el.innerHTML = `<h3>${it.name}</h3><p>${it.desc}</p><div class="price">${it.kind === 'blood' ? 'Costs 1 Integrity' : it.cost + ' stardust'}</div>`
      el.addEventListener('click', () => onPick(it))
      this.els.altarGrid.appendChild(el)
    })
    $('altar-leave').onclick = onLeave
  }

  hideAltar() {
    this.show(this.els.altar, false)
  }

  showPause(on) {
    this.show(this.els.pause, on)
  }

  showHow(on) {
    this.show(this.els.how, on)
  }

  showReliquary(meta, onBuy, onClose) {
    this.show(this.els.reliquary, true)
    this.els.ashBank.textContent = String(meta.ash)
    this.els.unlockGrid.innerHTML = ''
    UNLOCKS.forEach((u) => {
      const owned = !!meta.unlocks[u.id]
      const el = document.createElement('button')
      el.className = 'unlock-item' + (owned ? ' owned' : meta.ash < u.cost ? ' locked-cash' : '')
      el.innerHTML = `<h3>${u.name}</h3><p>${u.desc}</p><div class="price">${owned ? 'Unsealed' : u.cost + ' Ash'}</div>`
      if (!owned) el.addEventListener('click', () => onBuy(u))
      this.els.unlockGrid.appendChild(el)
    })
    $('reliquary-close').onclick = onClose
  }

  showResults(payload) {
    this.show(this.els.results, true)
    this.show(this.els.hud, false)
    this.els.resultsKicker.textContent = payload.win ? 'The still point yields' : 'The spark guttered'
    this.els.resultsTitle.textContent = payload.win ? 'Apotheosis' : 'Fallen'
    this.els.resultsLead.textContent = payload.lead
    this.els.resultsStats.innerHTML = payload.stats
      .map((s) => `<li>${s.k}<b>${s.v}</b></li>`)
      .join('')
    this.els.resultsUnlocks.textContent = payload.unlockNote || ''
  }
}
