    n.className = 'floater ' + cls
    n.textContent = text
    n.style.left = x + 'px'
    n.style.top = y + 'px'
    layer.appendChild(n)
    setTimeout(() => n.remove(), 720)
  }

  renderRun(game) {
    const p = game.player
    const floor = HEAVENS[game.floor] || HEAVENS[2]
    this.els.floor.textContent = floor.kicker
    this.els.chamber.textContent = game.roomKind === 'boss' ? floor.name : `Chamber ${game.chamber}`
    this.els.ash.textContent = String(game.stardust)
    this.els.align.textContent = '×' + game.alignMul.toFixed(game.alignMul % 1 ? 1 : 0)

    const max = p.maxHp
    const hp = p.hp
    const hold = this.els.integrity
    if (hold.childElementCount !== max) {
      hold.innerHTML = ''
      for (let i = 0; i < max; i++) {
        const pip = document.createElement('div')
        pip.className = 'pip'
        hold.appendChild(pip)
      }
    }
    ;[...hold.children].forEach((pip, i) => {
      pip.classList.toggle('on', hp >= i + 1)
      pip.classList.toggle('half', hp > i && hp < i + 1)
    })

    const orr = this.els.orrery
    const slots = game.rules.slots
    if (orr.childElementCount !== slots) {
      orr.innerHTML = ''
      for (let i = 0; i < slots; i++) {
        const s = document.createElement('div')
        s.className = 'orb-slot empty'
        s.innerHTML = '<i></i>'
        orr.appendChild(s)
      }
    }
    ;[...orr.children].forEach((slot, i) => {
      const o = game.orbiters[i]
      slot.classList.toggle('empty', !o)
      slot.classList.toggle('sel', i === game.selected)
      slot.classList.toggle('away', !!(o && o.mode !== 'orbit'))
      const ic = slot.querySelector('i')
      if (o) {
        ic.style.background = o.def.glow
        ic.style.color = o.def.glow
        ic.style.display = 'block'
      } else ic.style.display = 'none'
    })

    const dash = game.dashCd <= 0 && game.dashCharges > 0 ? 1 : 1 - game.dashCd / game.dashMax
    const pulse = 1 - game.pulseCd / game.rules.pulseCd
    const fling = 1 - game.flingCd / 0.22
    this.els.cdDash.style.transform = `scaleX(${Math.max(0, Math.min(1, dash))})`
    this.els.cdPulse.style.transform = `scaleX(${Math.max(0, Math.min(1, pulse))})`
    this.els.cdFling.style.transform = `scaleX(${Math.max(0, Math.min(1, fling))})`

    if (game.boss) {
      this.show(this.els.boss, true)
      this.els.bossName.textContent = game.boss.title || game.boss.name
      const t = Math.max(0, game.boss.hp / game.boss.maxHp)
      this.els.bossFill.style.transform = `scaleX(${t})`
    } else this.show(this.els.boss, false)
