const texCache = new Map()

export function glowTexture(hex = '#ffffff', size = 128) {
  const key = hex + size
  if (texCache.has(key)) return texCache.get(key)
  const c = document.createElement('canvas')
  c.width = c.height = size
  const g = c.getContext('2d')
  const grd = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  grd.addColorStop(0, hex)
  grd.addColorStop(0.22, hex)
  grd.addColorStop(0.55, hex + '88')
  grd.addColorStop(1, 'rgba(0,0,0,0)')
  g.fillStyle = grd
  g.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  texCache.set(key, tex)
  return tex
}

export function nebulaTexture() {
  const size = 256
  const c = document.createElement('canvas')
  c.width = c.height = size
  const g = c.getContext('2d')
  g.clearRect(0, 0, size, size)
  for (let i = 0; i < 8; i++) {
    const x = size * (0.2 + Math.random() * 0.6)
    const y = size * (0.2 + Math.random() * 0.6)
    const r = size * (0.18 + Math.random() * 0.28)
    const grd = g.createRadialGradient(x, y, 0, x, y, r)
    const hue = 250 + Math.random() * 80
    grd.addColorStop(0, `hsla(${hue}, 60%, 55%, 0.28)`)
    grd.addColorStop(1, 'rgba(0,0,0,0)')
    g.fillStyle = grd
    g.fillRect(0, 0, size, size)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function makeGlowSprite(color, scale = 2.4) {
  const hex = '#' + new THREE.Color(color).getHexString()
  const mat = new THREE.SpriteMaterial({
    map: glowTexture(hex),
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    opacity: 0.9,
  })
  const s = new THREE.Sprite(mat)
  s.scale.setScalar(scale)
