  }

  showHow(on) {
    this.show(this.els.how, on)
  }

  showReliquary(meta, onBuy, onClose) {
    this.show(this.els.reliquary, true)
    this.els.ashBank.textContent = String(meta.ash)
    this.els.unlockGrid.innerHTML = ''
    UNLOCKS.forEach((u) => {
      const owned = !!meta.unlocks[u.id]
      const el = document.createElement('button')
      el.className = 'unlock-item' + (owned ? ' owned' : meta.ash < u.cost ? ' locked-cash' : '')
      el.innerHTML = `<h3>${u.name}</h3><p>${u.desc}</p><div class="price">${owned ? 'Unsealed' : u.cost + ' Ash'}</div>`
      if (!owned) el.addEventListener('click', () => onBuy(u))
      this.els.unlockGrid.appendChild(el)
    })
    $('reliquary-close').onclick = onClose
  }

  showResults(payload) {
    this.show(this.els.results, true)
    this.show(this.els.hud, false)
    this.els.resultsKicker.textContent = payload.win ? 'The still point yields' : 'The spark guttered'
    this.els.resultsTitle.textContent = payload.win ? 'Apotheosis' : 'Fallen'
    this.els.resultsLead.textContent = payload.lead
    this.els.resultsStats.innerHTML = payload.stats
      .map((s) => `<li>${s.k}<b>${s.v}</b></li>`)
      .join('')
    this.els.resultsUnlocks.textContent = payload.unlockNote || ''
  }
}
