        const sm = hexShape({ shape: 'sphere', radius: 0.18, color: 0xe0b050, edge: 0xffe6a0 })
        mesh.add(sm)
        e.shields.push({ mesh: sm, a: (i / spec.shields) * TAU, hp: 12 })
      }
    }
    this.enemies.push(e)
    if (extra.isBossBar) this.boss = e
    return e
  }

  _spawnBoss() {
    const id = ['meridian', 'choir', 'still'][this.floor]
    const b = BOSSES[id]
    if (id === 'choir') {
      const members = []
      for (let i = 0; i < 3; i++) {
        const a = (i / 3) * TAU
        const e = this.spawnEnemy(
          'seer',
          Math.cos(a) * 6,
          Math.sin(a) * 6,
          {
            bossId: 'choir',
            title: b.title,
            hpMul: 3.2,
            def: {
              ...ENEMY.seer,
              name: b.name,
              hp: b.hp,
              radius: b.radius,
              color: 0x140814,
              edge: 0xff2d6a,
              shape: 'tetra',
              speed: b.speed,
            },
          },
        )
        members.push(e)
      }
      members.forEach((e) => {
        e.link = members
        e.maxHp = b.hp * 1.05
        e.hp = e.maxHp
      })
      this.boss = {
        name: b.name,
        title: b.title,
        get hp() {
          return members.reduce((s, m) => s + Math.max(0, m.hp), 0)
        },
        get maxHp() {
          return members.reduce((s, m) => s + m.maxHp, 0)
        },
        choir: members,
      }
      return
    }
    const mesh =
      id === 'meridian'
        ? this._meshMeridian()
        : this._meshStill()
    const e = this.spawnEnemy('ballast', 0, -5, {
      bossId: id,
      isBossBar: true,
      title: b.title,
      mesh,
      def: {
        name: b.name,
        hp: b.hp,
        radius: b.radius,
        speed: b.speed,
        color: 0x0c0812,
        edge: id === 'still' ? 0x7ee7ff : 0xe0b050,
        shape: 'ico',
        touch: 1,
      },
    })
    e.name = b.name
    e.title = b.title
    this.boss = e
  }

  _meshMeridian() {
    const g = new THREE.Group()
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(1.55, 0.22, 10, 40),
      new THREE.MeshStandardMaterial({
        color: 0x1a1210,
        emissive: 0x6a3a10,
        emissiveIntensity: 0.45,
        metalness: 0.7,
        roughness: 0.3,
      }),
    )
    ring.rotation.x = Math.PI / 2
    const core = hexShape({ shape: 'octa', radius: 0.55, color: 0x2a1810, edge: 0xe0b050 })
    g.add(ring, core)
    return g
  }

  _meshStill() {
    const g = new THREE.Group()
    const ball = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.5, 1),
      new THREE.MeshStandardMaterial({
        color: 0x05040a,
        emissive: 0x1a2040,
        emissiveIntensity: 0.5,
        roughness: 0.15,
        metalness: 0.8,
      }),
    )
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(2.1, 0.06, 8, 48),
      new THREE.MeshBasicMaterial({ color: 0x7ee7ff, transparent: true, opacity: 0.7 })
    )
    ring.rotation.x = Math.PI / 2
    g.add(ball, ring, makeGlowSprite(0x4a80ff, 5))
    return g
  }

  advanceRoom() {
    this.roomIndex += 1
    const seq = this.plan[this.floor]
    if (this.roomIndex >= seq.length) {
      this.floor += 1
      this.roomIndex = 0
      this.chamber = 1
      if (this.floor >= this.plan.length) {
        this.victory()
        return
      }
      this.ui.announce(HEAVENS[this.floor].name)
    } else this.chamber += 1
    this.beginRoom()
  }

  update(dt, input) {
    if (this.mode === 'title') {
      this._updateDemo(dt)
      return
    }
    if (this.mode === 'pause' || this.mode === 'cards' || this.mode === 'results') {
      this._spinMeshes(dt * 0.2)
      return
    }
    if (this.mode === 'altar') {
      this._updateBodies(dt * 0.6, input, true)
      return
    }
    if (this.mode !== 'play') return

    if (this.hitstop > 0) {
      this.hitstop -= dt
      dt *= 0.08
    }
    dt *= this.timeScale
    dt = Math.min(dt, 0.05)
    this.statsTime += dt

    this._updatePlayer(dt, input)
    this._updateOrbiters(dt, input)
    this._updateSyzygy(dt)
    this._updateEnemies(dt)
    this._updateBolts(dt)
    this._updatePickups(dt)
    this._updatePulses(dt)
    this._updateGhosts(dt)
    this._checkClear()
    this._hints(dt)
    this._spinMeshes(dt)
  }

  _updateDemo(dt) {
    this.demoAngle += dt * 0.15
    this.player.x = Math.cos(this.demoAngle) * 0.4
    this.player.z = Math.sin(this.demoAngle * 0.8) * 0.4
    this.orbitSign = 1
    this._updateOrbiters(dt, { aimx: 1, aimz: 0, fling: false, pulse: false, attract: false })
    this._updateSyzygy(dt)
    this._spinMeshes(dt)
  }

  _spinMeshes(dt) {
    if (this.playerCore) {
      this.playerCore.rotation.y += dt * 1.4
      this.playerCore.rotation.x += dt * 0.5
    }
    if (this.playerShell) {
      this.playerShell.rotation.y -= dt * 0.7
      this.playerShell.rotation.z += dt * 0.35
    }
    this.playerGroup.position.set(this.player.x, this.player.y, this.player.z)
    const pulse = 1 + Math.sin(performance.now() * 0.006) * 0.04
    this.playerGroup.scale.setScalar(pulse)
    this.orbiters.forEach((o, i) => {
      o.mesh.rotation.y += dt * (1.2 + i * 0.2)
      o.mesh.rotation.x += dt * 0.8
    })
  }

  _updatePlayer(dt, input) {
    const p = this.player
    const r = this.rules
    p.attract = input.attract
    const acc = 78 * r.moveMul
    const max = 11.2 * r.moveMul
    p.vx += input.x * acc * dt
    p.vz += input.z * acc * dt
    p.vx *= Math.exp(-6.4 * dt)
    p.vz *= Math.exp(-6.4 * dt)
    const sp = Math.hypot(p.vx, p.vz)
    if (sp > max && p.dashT <= 0) {
      p.vx = (p.vx / sp) * max
      p.vz = (p.vz / sp) * max
    }
    if (input.aimx || input.aimz) p.facing = Math.atan2(input.aimz, input.aimx)

    if (input.dash) this.tryDash(input)
    if (input.fling) this.tryFling(input)
    if (input.pulse) this.tryPulse()
    if (input.reverse) this.reverseOrbits()
    if (input.selDelta) {
      this.selected = (this.selected + input.selDelta + this.orbiters.length) % Math.max(1, this.orbiters.length)
    }

    this.dashCd = Math.max(0, this.dashCd - dt)
    if (this.dashCd <= 0 && this.dashCharges < r.dashes) {
      this.dashCharges = r.dashes
    }
    this.pulseCd = Math.max(0, this.pulseCd - dt)
    this.flingCd = Math.max(0, this.flingCd - dt)
    p.iframes = Math.max(0, p.iframes - dt)
    p.dashT = Math.max(0, p.dashT - dt)
    this.orbitFreeze = Math.max(0, this.orbitFreeze - dt)
    this.rules.spearLock = Math.max(0, this.rules.spearLock - dt)

    if (p.dashT > 0 && r.dashTrail && this.rng.chance(0.6)) {
      this.trailsWake.push({ x: p.x, z: p.z, t: 0.28 })
      this._hurtCircle(p.x, p.z, 0.7, 6, 0xff6a2a, false)
    }

    p.x += p.vx * dt
    p.z += p.vz * dt
    const c = clampArena(p.x, p.z, p.r)
    p.x = c.x
    p.z = c.z

    if (p.attract || r.corePull) {
      const rad = p.attract ? r.attractRad : 3.2
      const force = p.attract ? 16 : r.corePull
      this._attract(p.x, p.z, rad, force, dt)
    }
  }

  tryDash(input) {
    if (this.dashCharges <= 0) return
    const p = this.player
    let dx = input.x
    let dz = input.z
    if (!dx && !dz) {
      dx = Math.cos(p.facing)
      dz = Math.sin(p.facing)
    }
    const m = Math.hypot(dx, dz) || 1
    p.vx = (dx / m) * 36
    p.vz = (dz / m) * 36
    p.dashT = 0.13
    p.iframes = 0.2
    this.dashCharges -= 1
    this.dashCd = this.dashMax
    this.audio.dash()
    this.fx.burst(p.x, p.y, p.z, 0xffe6b0, 16, 8, 0.35, 0.18)
    this.world.rig.shake(0.18)
    if (this.rules.afterimage) {
      const mesh = hexShape({ shape: 'ico', radius: 0.35, color: 0xffe6b0, edge: 0xffe6b0 })
      mesh.position.set(p.x, p.y, p.z)
      this.scene.add(mesh)
      this.ghosts.push({ mesh, t: 0.45, x: p.x, z: p.z })
    }
  }

  tryFling(input) {
    if (this.flingCd > 0 || !this.orbiters.length) return
    const aimA = Math.atan2(input.aimz, input.aimx)
    let best = this.orbiters[this.selected]
    let bestD = 99
    for (const o of this.orbiters) {
      if (o.mode !== 'orbit') continue
      const d = angDiff(o.angle, aimA)
      if (d < bestD) {
        bestD = d
        best = o
      }
    }
    if (!best || best.mode !== 'orbit') return
    const spear = this.syzygyOn || this.rules.spearLock > 0 || this.rules.easySpear
    best.mode = 'flung'
    best.life = this.rules.flingTime * (spear ? 1.25 : 1)
    const s = (spear ? 42 : 30) * (0.85 + best.def.mass * 0.1)
    const dx = input.aimx
    const dz = input.aimz
    const m = Math.hypot(dx, dz) || 1
    best.fx = (dx / m) * s
    best.fz = (dz / m) * s
    best.pierce = this.rules.flingPierce + (spear ? 3 : 0)
    best.spear = spear
    best.hitAt.clear()
    this.flingCd = 0.22
    this.selected = this.orbiters.indexOf(best)
    this.audio.fling()
    if (spear) {
      this.spears += 1
      this.ui.syzygy('SPEAR')
      this.audio.syzygy()
      this.fx.ring(best.mesh.position.x, 0.6, best.mesh.position.z, best.def.color, 18, 10)
    }
  }

  tryPulse() {
    if (this.pulseCd > 0) return
    const nova = this.syzygyOn || this.syzygyHold > 0
    const rad = this.rules.pulseRad * (nova ? 1.55 : 1)
    const dmg = this.rules.pulseDmg * (nova ? 1.8 : 1) * this.alignMul
    this.pulses.push({
      x: this.player.x,
      z: this.player.z,
      r: 0.4,
      max: rad,
      dmg,
      hit: new Set(),
      nova,
    })
    this.pulseCd = this.rules.pulseCd * (nova ? 0.85 : 1)
    this.fx.ring(this.player.x, 0.4, this.player.z, nova ? 0xffe6a0 : 0x7ee7ff, nova ? 36 : 22, nova ? 14 : 9)
    this.world.rig.shake(nova ? 0.55 : 0.28)
    this.world.pulse = 1
    if (nova) {
      this.novas += 1
      this.ui.syzygy('NOVA')
      this.audio.nova()
      this.ui.flash('#fff3c0', 70)
      this.hitstop = 0.07
    } else this.audio.pulse()
    if (this.rules.nullTongue) {
      for (let i = this.bolts.length - 1; i >= 0; i--) {
        const b = this.bolts[i]
        if (b.friendly) continue
        if (Math.hypot(b.x - this.player.x, b.z - this.player.z) < rad + 1.5) {
          this.fx.burst(b.x, 0.5, b.z, 0x7ee7ff, 6, 4, 0.25)
          nuke(b.mesh)
          this.bolts.splice(i, 1)
        }
      }
    }
  }

  reverseOrbits() {
    this.orbitSign *= -1
    this.audio.reverse()
    this.fx.ring(this.player.x, 0.5, this.player.z, 0xb48cff, 16, 7)
  }

  _orbiterPos(o) {
    const ecc = o.def.ecc || 0
    let rad = o.baseR * this.rules.radiusMul
    if (ecc) rad *= 1 + ecc * Math.cos(o.angle)
    return {
      x: this.player.x + Math.cos(o.angle) * rad,
      z: this.player.z + Math.sin(o.angle) * rad,
      y: 0.62 + Math.sin(o.angle * 2) * 0.08,
      rad,
    }
  }

  _updateOrbiters(dt, input) {
    if (this.orbitFreeze <= 0) {
      /* angles advance */
    }
    for (const o of this.orbiters) {
      const slot = this._orbiterPos(o)
      if (o.mode === 'orbit') {
        if (this.orbitFreeze <= 0) o.angle += o.def.spin * this.rules.orbitMul * this.orbitSign * dt
        if (o.angle > TAU) {
          o.angle -= TAU
          o.laps += 1
          if (o.def.mend) this.heal(o.def.mend)
        }
        if (o.angle < 0) o.angle += TAU
        o.mesh.position.set(slot.x, slot.y, slot.z)
      } else if (o.mode === 'flung') {
        o.life -= dt
        o.mesh.position.x += o.fx * dt
        o.mesh.position.z += o.fz * dt
        o.mesh.position.y = 0.7
        const c = clampArena(o.mesh.position.x, o.mesh.position.z, 0.2)
        if (c.x !== o.mesh.position.x || c.z !== o.mesh.position.z) {
          o.fx *= -0.4
          o.fz *= -0.4
          o.mesh.position.x = c.x
          o.mesh.position.z = c.z
        }
        if (o.life <= 0) o.mode = 'return'
      } else if (o.mode === 'return') {
        const dx = slot.x - o.mesh.position.x
        const dz = slot.z - o.mesh.position.z
        const d = Math.hypot(dx, dz)
        const sp = 26 * this.rules.returnMul
        if (d < 0.35) {
          o.mode = 'orbit'
          o.spear = false
        } else {
          o.mesh.position.x += (dx / d) * sp * dt
          o.mesh.position.z += (dz / d) * sp * dt
          o.mesh.position.y = 0.66
        }
      }
      o.glow.position.copy(o.mesh.position)
      o.trail.push(o.mesh.position.x, o.mesh.position.y, o.mesh.position.z)
      if (o.def.color === RELICS.prism.color) {
        const hue = (performance.now() * 0.0002 + o.angle) % 1
        const c = new THREE.Color().setHSL(hue, 0.75, 0.6)
        o.mesh.material.emissive.copy(c)
        o.trail.setColor(c)
      }

      this._orbiterHits(o)

      if (this.rules.solarWind && o.mode === 'orbit') {
        o.windT -= dt
        if (o.windT <= 0) {
          o.windT = 0.55
          const dx = o.mesh.position.x - this.player.x
          const dz = o.mesh.position.z - this.player.z
          const m = Math.hypot(dx, dz) || 1
          this.spawnBolt(o.mesh.position.x, o.mesh.position.z, (dx / m) * 10, (dz / m) * 10, 6, true, o.def.color)
        }
      }
    }
  }

  _orbiterHits(o) {
    const dmgBase = o.def.dmg * this.rules.contactMul * (o.mode === 'flung' ? this.rules.flingMul * (o.spear ? 1.8 : 1) : 1)
    let peri = 1
    if (this.rules.periapsis !== 1 && o.mode === 'orbit') {
      const slot = this._orbiterPos(o)
      const close = o.baseR * this.rules.radiusMul * (1 - (o.def.ecc || 0))
      if (slot.rad < close + 0.55) peri = this.rules.periapsis
    }
    const px = o.mesh.position.x
    const pz = o.mesh.position.z
    for (const e of this.enemies) {
      const d = Math.hypot(px - e.x, pz - e.z)
      if (d > o.def.radius + e.r + 0.08) continue
      const now = this.statsTime
      const last = o.hitAt.get(e) || -9
      const gap = o.mode === 'flung' ? 0.12 : 0.28
      if (now - last < gap) continue
      o.hitAt.set(e, now)
      let dmg = dmgBase * peri * this.alignMul
      if (o.def.crit && this.rng.chance(o.def.crit)) dmg *= 2
      if (o.def.slow) e.slow = Math.min(e.slow, 1 - o.def.slow)
      if (o.def.pull) {
        const ang = Math.atan2(pz - e.z, px - e.x)
        e.vx += Math.cos(ang) * o.def.pull
        e.vz += Math.sin(ang) * o.def.pull
      }
      if (o.def.execute && e.hp / e.maxHp < o.def.execute) dmg = Math.max(dmg, e.hp + 1)
      this.hurt(e, dmg, o.def.color, o.mode === 'flung' || o.spear)
      if (o.mode === 'flung') {
        o.pierce -= 1
        if (o.pierce < 0) o.mode = 'return'
      }
      if (o.def.fork || this.rules.fork) {
        if (this.rng.chance(o.def.fork ? 1 : this.rules.fork)) this._fork(e, dmg * 0.45, o.def.color)
      }
    }
    if (this.rules.horizon && o.mode === 'orbit') {
      const inner = 2.2 * this.rules.radiusMul
      for (const e of this.enemies) {
        if (e.hp / e.maxHp < this.rules.horizon && Math.hypot(e.x - this.player.x, e.z - this.player.z) < inner) {
          this.hurt(e, e.hp + 5, 0x220011, true)
        }
      }
    }
  }

  _fork(from, dmg, color) {
    let best = null
    let bd = 6.5
    for (const e of this.enemies) {
      if (e === from || e.hp <= 0) continue
      const d = Math.hypot(e.x - from.x, e.z - from.z)
      if (d < bd) {
        bd = d
        best = e
      }
    }
    if (best) this.hurt(best, dmg, color, false)
  }

  _updateSyzygy(dt) {
    const win = this.rules.syzygyWindow
    const pairs = []
    const n = this.orbiters.length
    for (let i = 0; i < n; i++) {
      const a = this.orbiters[i]
      if (a.mode !== 'orbit') continue
      for (let j = i + 1; j < n; j++) {
        const b = this.orbiters[j]
        if (b.mode !== 'orbit') continue
        const d = angDiff(a.angle, b.angle)
        const opposite = Math.abs(d - Math.PI) < win
        const conjunct = d < win * 0.85
        const any = this.rules.constellation && d < win * 1.4
        if (opposite || conjunct || any) {
          pairs.push({ a, b, ang: opposite || conjunct ? a.angle : Math.atan2(b.mesh.position.z - a.mesh.position.z, b.mesh.position.x - a.mesh.position.x), through: opposite || conjunct })
        }
      }
    }
    const was = this.syzygyOn
    this.syzygyOn = pairs.some((p) => p.through)
    if (this.syzygyOn) {
      this.syzygyHold = 0.28
      this.world.syzygy = 1
      if (!was) {
        this.syzygies += 1
        this.audio.syzygy()
        this.ui.syzygy('SYZYGY')
        this.rules.spearLock = 0.45
      }
    } else this.syzygyHold = Math.max(0, this.syzygyHold - dt)

    this.beamPool.forEach((b) => {
      b.life -= dt
      if (b.life <= 0) {
        b.mesh.visible = false
        b.mat.opacity = 0
      }
    })
    pairs.forEach((p, i) => {
      const beam = this.beamPool[i % this.beamPool.length]
      beam.life = this.rules.beamTime
      beam.ang = p.ang
      beam.mesh.visible = true
      const len = ARENA * 2.1
      beam.mesh.scale.set(len, p.through ? 1.4 : 0.8, p.through ? 1.3 : 0.7)
      beam.mesh.position.set(this.player.x, 0.45, this.player.z)
      beam.mesh.rotation.set(0, -p.ang, 0)
      beam.mat.opacity = p.through ? 0.55 : 0.28
      beam.mat.color.set(p.through ? 0xffe08a : 0x7ee7ff)
      const dmg = this.rules.beamDmg * this.rules.beamMul * this.alignMul * dt
      for (const e of this.enemies) {
        const dist = this._distToAxis(e.x, e.z, this.player.x, this.player.z, p.ang)
        if (dist < e.r + 0.38) this.hurt(e, dmg, 0xffe08a, false, true)
      }
    })

    this.alignIdle += dt
    if (this.alignIdle > 2.2) this.alignMul = Math.max(1, this.alignMul - dt * 0.35)
  }

  _distToAxis(x, z, ox, oz, ang) {
    const ca = Math.cos(ang)
    const sa = Math.sin(ang)
    const dx = x - ox
    const dz = z - oz
    return Math.abs(dx * sa - dz * ca)
  }

  _updateEnemies(dt) {
    const p = this.player
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i]
      if (e.hp <= 0) {
        this._kill(e)
        this.enemies.splice(i, 1)
        continue
      }
      e.stun = Math.max(0, e.stun - dt)
      e.flash = Math.max(0, e.flash - dt)
      e.slow = Math.min(1, e.slow + dt * 0.35)
      const can = e.stun <= 0
      const spd = (e.def.speed || 2.4) * e.slow
      const dx = p.x - e.x
      const dz = p.z - e.z
      const dist = Math.hypot(dx, dz) || 0.001
      const ux = dx / dist
      const uz = dz / dist

      if (can && e.boss === 'meridian') this._aiMeridian(e, dt, ux, uz, dist)
      else if (can && e.boss === 'choir') this._aiChoir(e, dt, ux, uz, dist)
      else if (can && e.boss === 'still') this._aiStill(e, dt, ux, uz, dist)
      else if (can) this._aiBasic(e, dt, ux, uz, dist, spd)

      e.x += e.vx * dt
      e.z += e.vz * dt
      e.vx *= Math.exp(-3.5 * dt)
      e.vz *= Math.exp(-3.5 * dt)
      const c = clampArena(e.x, e.z, e.r)
      e.x = c.x
      e.z = c.z
      e.mesh.position.set(e.x, e.y, e.z)
      if (e.boss === 'meridian') e.mesh.rotation.z += dt * 1.2
      else e.mesh.rotation.y += dt * 1.4

      if (e.shields) {
        e.shields.forEach((s) => {
          s.a += dt * 2.2
          s.mesh.position.set(Math.cos(s.a) * 1.4, 0.1, Math.sin(s.a) * 1.4)
        })
      }

      if (e.flash > 0) e.mesh.traverse((o) => {
        if (o.material && o.material.emissive) o.material.emissiveIntensity = 1.8
      })
      else e.mesh.traverse((o) => {
        if (o.material && o.material.emissive && o.material.userData.base == null) {
          /* keep */
        }
      })

      if (p.iframes <= 0 && p.dashT <= 0 && Math.hypot(p.x - e.x, p.z - e.z) < p.r + e.r * 0.85) {
        this.hitPlayer(1, ux, uz)
      }
    }
  }

  _aiBasic(e, dt, ux, uz, dist, spd) {
    const t = e.type
    if (t === 'seer') {
      const want = 8
      e.vx += (dist > want ? ux : -ux) * spd * 3 * dt
      e.vz += (dist > want ? uz : -uz) * spd * 3 * dt
      e.shootT -= dt
      if (e.shootT <= 0) {
        e.shootT = (e.def.shoot || 1.8) * (0.8 + this.rng.range(0, 0.4))
        this.spawnBolt(e.x, e.z, ux * 9, uz * 9, 1, false, 0x7ee7ff)
      }
    } else if (t === 'splinter') {
      e.vx += ux * spd * 4 * dt
      e.vz += uz * spd * 4 * dt
      e.dashT -= dt
      if (e.dashT <= 0) {
        e.dashT = 2.1
        e.vx += ux * 18
        e.vz += uz * 18
        e.tele = 0.12
      }
    } else if (t === 'ballast') {
      e.vx += ux * spd * 2.4 * dt
      e.vz += uz * spd * 2.4 * dt
      e.slamT -= dt
      if (e.slamT <= 0.7 && e.slamT > 0) e.tele = e.slamT
      if (e.slamT <= 0) {
        e.slamT = 3.4
        this._hurtCircle(e.x, e.z, 2.6, 1, 0xb48cff, true)
        this.fx.ring(e.x, 0.2, e.z, 0xb48cff, 20, 8)
        e.stun = 0.25
      }
    } else if (t === 'ravel') {
      e.vx += (dist > 7 ? ux : -ux) * spd * 3 * dt
      e.vz += (dist > 7 ? uz : -uz) * spd * 3 * dt
      e.spawnT -= dt
      if (e.spawnT <= 0) {
        e.spawnT = 3.6
        this.spawnEnemy('mite', e.x + ux * -1.2, e.z + uz * -1.2)
      }
    } else if (t === 'eclipse') {
      e.vx += (dist > 7 ? ux : -ux) * spd * 2.5 * dt
      e.vz += (dist > 7 ? uz : -uz) * spd * 2.5 * dt
      e.beamT -= dt
      if (e.beamT < 0.8 && e.beamT > 0) {
        this._paintBeam(e.x, e.z, Math.atan2(uz, ux), 0.15)
      }
      if (e.beamT <= 0) {
        e.beamT = 3.2
        this._axisBurst(e.x, e.z, Math.atan2(uz, ux), 1)
        this.audio.hit(true)
      }
    } else if (t === 'warden') {
      e.vx += ux * spd * 2.6 * dt
      e.vz += uz * spd * 2.6 * dt
      e.shootT -= dt
      if (e.shootT <= 0) {
        e.shootT = 2.1
        for (let k = -1; k <= 1; k++) {
          const a = Math.atan2(uz, ux) + k * 0.22
          this.spawnBolt(e.x, e.z, Math.cos(a) * 8, Math.sin(a) * 8, 1, false, 0xe0b050)
        }
      }
    } else {
      e.vx += ux * spd * 3.4 * dt
      e.vz += uz * spd * 3.4 * dt
    }
  }

  _aiMeridian(e, dt, ux, uz, dist) {
    e.mesh.children[0] && (e.mesh.children[0].rotation.z += dt * 1.6)
    const t = this.statsTime
    e.x += Math.cos(t * 0.7) * dt * 1.4
    e.vx += -uz * 6 * dt + ux * 2 * dt
    e.vz += ux * 6 * dt + uz * 2 * dt
    e.shootT -= dt
    if (e.shootT <= 0) {
      e.shootT = e.hp < e.maxHp * 0.5 ? 1.1 : 1.7
      const base = Math.atan2(uz, ux)
      const n = e.hp < e.maxHp * 0.5 ? 10 : 7
      for (let i = 0; i < n; i++) {
        const a = base + (i - n / 2) * 0.18
        this.spawnBolt(e.x, e.z, Math.cos(a) * 8, Math.sin(a) * 8, 1, false, 0xe0b050)
      }
    }
    e.spawnT = (e.spawnT || 4) - dt
    if (e.spawnT <= 0) {
      e.spawnT = 5
      this.spawnEnemy('husk', e.x + 2, e.z)
    }
    if (dist < 3.2) {
      this.player.vx += ux * 10 * dt
      this.player.vz += uz * 10 * dt
    }
  }

  _aiChoir(e, dt, ux, uz, dist) {
    const want = 6.2
    e.vx += (dist > want ? ux : -ux) * 8 * dt
    e.vz += (dist > want ? uz : -uz) * 8 * dt
    e.shootT -= dt
    if (e.shootT <= 0) {
      e.shootT = 1.5
      this.spawnBolt(e.x, e.z, ux * 9, uz * 9, 1, false, 0xff2d6a)
    }
    if (e.link) {
      for (const o of e.link) {
        if (o === e || o.hp <= 0) continue
        const ang = Math.atan2(o.z - e.z, o.x - e.x)
        const d = Math.hypot(o.x - e.x, o.z - e.z)
        this._paintBeam(e.x, e.z, ang, 0.08, d)
        const dd = this._distToAxis(this.player.x, this.player.z, e.x, e.z, ang)
        const along = (this.player.x - e.x) * Math.cos(ang) + (this.player.z - e.z) * Math.sin(ang)
        if (dd < 0.45 && along > 0 && along < d && this.player.iframes <= 0) this.hitPlayer(1, ux, uz)
      }
    }
  }

  _aiStill(e, dt, ux, uz, dist) {
    e.vx += -ux * 1.2 * dt
    e.vz += -uz * 1.2 * dt
    const pull = e.hp < e.maxHp * 0.4 ? 10 : 5
    this.player.vx -= ux * pull * dt
    this.player.vz -= uz * pull * dt
    e.shootT -= dt
    if (e.shootT <= 0) {
      e.shootT = 1.3
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + this.statsTime
        this.spawnBolt(e.x, e.z, Math.cos(a) * 7, Math.sin(a) * 7, 1, false, 0x7ee7ff)
      }
    }
    e.slamT -= dt
    if (e.slamT < 1.1 && e.slamT > 0 && Math.floor(e.slamT * 10) % 2 === 0) {
      this.world.syzygy = 0.6
    }
    if (e.slamT <= 0) {
      e.slamT = 6.5
      this.orbitFreeze = 2.1
      this.ui.announce('STILL')
      this.audio.pulse()
      this.fx.ring(e.x, 0.6, e.z, 0x7ee7ff, 40, 16)
      this.world.rig.shake(0.5)
    }
    if (e.hp < e.maxHp * 0.35 && e.phase === 1) {
      e.phase = 2
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * TAU
        this.spawnEnemy('splinter', e.x + Math.cos(a) * 4, e.z + Math.sin(a) * 4)
      }
      this.ui.announce('The Point fractures')
    }
  }

  _paintBeam(x, z, ang, opacity, len = ARENA) {
    const beam = this.beamPool[this.beamPool.length - 1]
    beam.life = Math.max(beam.life, 0.08)
    beam.mesh.visible = true
    beam.mesh.position.set(x + Math.cos(ang) * len * 0.5, 0.3, z + Math.sin(ang) * len * 0.5)
    beam.mesh.rotation.set(0, -ang, 0)
    beam.mesh.scale.set(len, 0.7, 0.7)
    beam.mat.opacity = opacity
    beam.mat.color.set(0xff2d6a)
  }

  _axisBurst(x, z, ang, dmg) {
    for (const target of [this.player]) {
      const dist = this._distToAxis(target.x, target.z, x, z, ang)
      if (dist < 0.7) this.hitPlayer(dmg, Math.cos(ang), Math.sin(ang))
    }
    for (let i = 0; i < 10; i++) {
      const d = i * 1.6
      this.fx.burst(x + Math.cos(ang) * d, 0.4, z + Math.sin(ang) * d, 0xff2d6a, 4, 3, 0.25)
    }
  }

  spawnBolt(x, z, vx, vz, dmg, friendly, color) {
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(friendly ? 0.12 : 0.16, 8, 8),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 }),
    )
    const glow = makeGlowSprite(color, friendly ? 0.7 : 0.95)
    mesh.add(glow)
    mesh.position.set(x, 0.55, z)
    this.scene.add(mesh)
    this.bolts.push({ x, z, vx, vz, dmg, friendly, mesh, life: 3.2, r: 0.18, color })
  }

  _updateBolts(dt) {
    for (let i = this.bolts.length - 1; i >= 0; i--) {
      const b = this.bolts[i]
      b.life -= dt
      b.x += b.vx * dt
      b.z += b.vz * dt
      b.mesh.position.set(b.x, 0.55, b.z)
      const out = Math.hypot(b.x, b.z) > ARENA + 1
      if (b.life <= 0 || out) {
        nuke(b.mesh)
        this.bolts.splice(i, 1)
        continue
      }
      if (b.friendly) {
        for (const e of this.enemies) {
          if (Math.hypot(b.x - e.x, b.z - e.z) < e.r + b.r) {
            this.hurt(e, b.dmg, b.color, false)
            nuke(b.mesh)
            this.bolts.splice(i, 1)
            break
          }
        }
      } else if

 (this.player.iframes <= 0 && Math.hypot(b.x - this.player.x, b.z - this.player.z) < this.player.r + b.r) {
        const ux = b.x - this.player.x
        const uz = b.z - this.player.z
        this.hitPlayer(b.dmg, ux, uz)
        nuke(b.mesh)
        this.bolts.splice(i, 1)
      }
    }
  }

  _updatePickups(dt) {
    const p = this.player
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const u = this.pickups[i]
      u.t += dt
      u.mesh.position.y = 0.45 + Math.sin(u.t * 3) * 0.1
      u.mesh.rotation.y += dt * 2
      const d = Math.hypot(u.x - p.x, u.z - p.z)
      const pull = p.attract || this.rules.corePull ? 18 : 0
      if (d < 4.5 && pull) {
        const f = ((4.5 - d) / 4.5) * pull * dt
        u.x += ((p.x - u.x) / (d || 1)) * f
        u.z += ((p.z - u.z) / (d || 1)) * f
        u.mesh.position.x = u.x
        u.mesh.position.z = u.z
      }
      if (d < 0.85) {
        this._collect(u)
        nuke(u.mesh)
        this.pickups.splice(i, 1)
      }
    }
  }

  _collect(u) {
    this.audio.pickup()
    if (u.kind === 'dust') {
      this.stardust += u.n
      this.fx.burst(u.x, 0.5, u.z, 0xe0b050, 8, 4, 0.3)
    } else if (u.kind === 'heart') {
      this.heal(1)
    } else if (u.kind === 'relic') {
      if (this.orbiters.length >= this.rules.slots) this.rules.slots += 1
      this.addOrbiter(u.id)
      this.audio.relic()
      this.ui.announce(RELICS[u.id].name)
    }
  }

  spawnPickup(kind, x, z, extra = {}) {
    const col = kind === 'heart' ? 0x9dffb0 : kind === 'relic' ? RELICS[extra.id]?.color || 0xffe6a0 : 0xe0b050
    const mesh = hexShape({
      shape: kind === 'relic' ? RELICS[extra.id]?.shape || 'sphere' : kind === 'heart' ? 'octa' : 'ico',
      radius: kind === 'relic' ? 0.28 : 0.18,
      color: col,
      edge: col,
    })
    const p = clampArena(x, z, 0.3)
    mesh.position.set(p.x, 0.45, p.z)
    this.scene.add(mesh)
    this.pickups.push({ kind, x: p.x, z: p.z, mesh, t: 0, n: extra.n || 3, id: extra.id })
  }

  _updatePulses(dt) {
    for (let i = this.pulses.length - 1; i >= 0; i--) {
      const p = this.pulses[i]
      p.r += dt * 22
      for (const e of this.enemies) {
        if (p.hit.has(e)) continue
        const d = Math.hypot(e.x - p.x, e.z - p.z)
        if (d < p.r + e.r && d > p.r - 1.2) {
          p.hit.add(e)
          this.hurt(e, p.dmg, p.nova ? 0xffe08a : 0x7ee7ff, true)
          if (this.rules.chronoPulse) e.stun = Math.max(e.stun, this.rules.chronoPulse)
        }
      }
      if (p.r >= p.max) this.pulses.splice(i, 1)
    }
  }

  _updateGhosts(dt) {
    for (let i = this.ghosts.length - 1; i >= 0; i--) {
      const g = this.ghosts[i]
      g.t -= dt
      g.mesh.scale.setScalar(Math.max(0.1, g.t * 2))
      if (g.t <= 0) {
        this._hurtCircle(g.x, g.z, 2.1, 14, 0xffe6a0, false)
        this.fx.ring(g.x, 0.4, g.z, 0xffe6a0, 18, 10)
        nuke(g.mesh)
        this.ghosts.splice(i, 1)
      }
    }
  }

  _attract(x, z, rad, force, dt) {
    for (const e of this.enemies) {
      if (e.def.heavy || e.boss) continue
      const d = Math.hypot(e.x - x, e.z - z)
      if (d < rad && d > 0.2) {
        const f = ((rad - d) / rad) * force * dt * (e.type === 'mite' ? 1.4 : 0.55)
        e.vx += ((x - e.x) / d) * f
        e.vz += ((z - e.z) / d) * f
      }
    }
  }

  _hurtCircle(x, z, rad, dmg, color, vsPlayer) {
    if (vsPlayer && Math.hypot(this.player.x - x, this.player.z - z) < rad + this.player.r) {
      this.hitPlayer(dmg > 4 ? 1 : dmg, this.player.x - x, this.player.z - z)
    }
    if (!vsPlayer) {
      for (const e of this.enemies) {
        if (Math.hypot(e.x - x, e.z - z) < rad + e.r) this.hurt(e, dmg, color, true)
      }
    }
  }

  hurt(e, amount, color, heavy, tick) {
    if (e.hp <= 0) return
    if (e.shields && e.shields.length) {
      const s = e.shields[0]
      s.hp -= amount
      if (s.hp <= 0) {
        e.shields.shift()
        nuke(s.mesh)
      }
      return
    }
    e.hp -= amount
    e.flash = 0.08
    if (!tick) {
      this.fx.burst(e.x, e.y, e.z, color, heavy ? 14 : 7, heavy ? 7 : 4, 0.3, 0.16)
      this.audio.hit(heavy)
      this._float(e.x, e.y, e.z, Math.max(1, Math.round(amount)), heavy ? 'crit' : '')
      if (heavy) {
        this.hitstop = Math.max(this.hitstop, 0.04)
        this.world.rig.shake(0.12)
      }
    } else if (this.rng.chance(0.08)) {
      this._float(e.x, e.y + 0.3, e.z, Math.max(1, Math.round(amount)), 'sy')
    }
  }

  _kill(e) {
    this.kills += 1
    this.stardust += e.ash || 1
    this.ashEarned += e.ash || 1
    this.fx.burst(e.x, e.y, e.z, e.def.edge || 0xff2d6a, 22, 9, 0.45, 0.2)
    this.fx.ring(e.x, 0.3, e.z, e.def.edge || 0xff2d6a, 14, 7)
    nuke(e.mesh)
    if (this.syzygyOn || this.syzygyHold > 0) {
      this.alignMul = Math.min(4, this.alignMul + 0.5)
      this.alignIdle = 0
    }
    if (this.rules.killRefund) this.pulseCd = Math.max(0, this.pulseCd - this.rules.pulseCd * this.rules.killRefund)
    if (this.rules.harvestEvery) {
      this.rules.harvestCount += 1
      if (this.rules.harvestCount >= this.rules.harvestEvery) {
        this.rules.harvestCount = 0
        this.heal(0.5)
      }
    }
    if (this.rng.chance(0.22)) this.spawnPickup('dust', e.x, e.z, { n: this.rng.int(2, 5) })
    if (e.elite && this.rng.chance(0.85)) {
      const id = this.rng.pick(Object.keys(RELICS))
      this.spawnPickup('relic', e.x + 0.4, e.z, { id })
    }
    if (e.boss && e.boss !== 'choir') {
      const id = this.rng.pick(['comet', 'nullseed', 'prism', 'heartwood'])
      this.spawnPickup('relic', e.x, e.z, { id })
      this.spawnPickup('heart', e.x + 1, e.z)
    }
    if (e.boss === 'choir' && e.link && e.link.every((m) => m === e || m.hp <= 0)) {
      this.spawnPickup('relic', e.x, e.z, { id: 'nullseed' })
    }
  }

  hitPlayer(raw, ux, uz) {
    const p = this.player
    if (p.iframes > 0) return
    if (this.rules.hymnReady) {
      this.rules.hymnReady = false
      p.iframes = 0.6
      this.ui.announce('Iron Hymn')
      this.fx.ring(p.x, 0.5, p.z, 0xe0b050, 18, 8)
      return
    }
    let dmg = Math.max(1, raw - this.rules.flatReduce)
    p.hp -= dmg
    p.iframes = 0.7
    const m = Math.hypot(ux, uz) || 1
    p.vx -= (ux / m) * 14
    p.vz -= (uz / m) * 14
    this.audio.playerHit()
    this.ui.flash('#ff2d6a', 80)
    this.world.rig.shake(0.45)
    this.fx.burst(p.x, p.y, p.z, 0xff2d6a, 18, 8, 0.4)
    this.hitstop = 0.08
    if (p.hp <= 0) this.die()
  }

  heal(n) {
    const before = this.player.hp
    this.player.hp = Math.min(this.player.maxHp, this.player.hp + n)
    if (this.player.hp > before) this._float(this.player.x, 1.2, this.player.z, '+' + (n % 1 ? n.toFixed(1) : n), 'heal')
  }

  _float(x, y, z, text, cls) {
    const s = worldToScreen(new THREE.Vector3(x, y, z), this.camera, this.canvas)
    this.ui.float(this.floatLayer, s.x, s.y, String(text), cls)
  }

  _checkClear() {
    if (this.cleared || this.mode !== 'play') return
    if (this.roomKind === 'altar') return
    if (this.enemies.length > 0) return
    if (this.wave < this.waves && this.roomKind !== 'boss') {
      this._spawnWave()
      return
    }
    if (this.roomKind === 'boss' && this.boss && this.boss.choir && this.boss.hp > 0) return
    this.cleared = true
    this.stardust += 6 + this.floor * 3
    this.ashEarned += this.roomKind === 'boss' ? 18 : this.roomKind === 'elite' ? 8 : 3
    if (this.roomKind === 'boss' && this.floor >= 2) {
      this.victory()
      return
    }
    setTimeout(() => {
      if (this.mode !== 'play') return
      if (this.roomKind === 'boss') {
        this.heal(1)
        this.advanceRoom()
      } else this.offerEdicts(false)
    }, 650)
  }

  offerEdicts() {
    const pool = EDICTS.filter((e) => {
      if (e.unlock && !this.meta.unlocks[e.unlock]) return false
      if (e.once && this.applied.has(e.id)) return false
      return true
    })
    const pickRarity = () => {
      const r = this.rng.next()
      if (r < 0.08) return 'legendary'
      if (r < 0.38) return 'rare'
      return 'common'
    }
    const choices = []
    for (let k = 0; k < 3; k++) {
      let rarity = pickRarity()
      let slice = pool.filter((e) => e.rarity === rarity && !choices.includes(e))
      if (!slice.length) slice = pool.filter((e) => !choices.includes(e))
      if (!slice.length) break
      choices.push(this.rng.pick(slice))
    }
    if (!choices.length) {
      this.heal(1)
      this.advanceRoom()
      return
    }
    this.mode = 'cards'
    this.audio.card()
    this.ui.showCards(choices, (ed) => this.pickEdict(ed))
  }

  pickEdict(ed) {
    ed.apply(this.rules, this)
    this.applied.add(ed.id)
    this.taken.push(ed.name)
    this.audio.ui()
    this.ui.hideCards()
    this.ui.announce(ed.name)
    this.advanceRoom()
  }

  die() {
    if (this.mode === 'results') return
    this.mode = 'results'
    this.audio.death()
    this.fx.burst(this.player.x, this.player.y, this.player.z, 0xffe6b0, 40, 12, 0.7, 0.24)
    this._finish(false)
  }

  victory() {
    if (this.mode === 'results') return
    this.mode = 'results'
    this.audio.win()
    this.ui.flash('#ffe6a0', 200)
    this._finish(true)
  }

  _finish(win) {
    const ashMul = this.meta.unlocks.ashen ? 1.25 : 1
    const ash = Math.floor((this.ashEarned + Math.floor(this.stardust * 0.25) + (win ? 40 : 0)) * ashMul)
    this.lastResult = {
      win,
      ash,
      kills: this.kills,
      time: this.statsTime,
      syzygies: this.syzygies,
      novas: this.novas,
      spears: this.spears,
      floor: this.floor,
      chamber: this.chamber,
    }
    this.ui.showResults({
      win,
      lead: win
        ? 'You aligned the last law. The engine of heaven turns once more — for now.'
        : 'The Null unspooled your wheel. Ash remains. The Reliquary remembers.',
      stats: [
        { k: 'Ash gained', v: ash },
        { k: 'Kills', v: this.kills },
        { k: 'Syzygies', v: this.syzygies },
        { k: 'Novas / Spears', v: `${this.novas} / ${this.spears}` },
        { k: 'Time', v: formatTime(this.statsTime) },
        { k: 'Edicts', v: this.taken.length ? this.taken.slice(0, 4).join(', ') : '—' },
      ],
    })
  }
}

function formatTime(t) {
  const m = Math.floor(t / 60)
  const s = Math.floor(t % 60)
  return `${m}:${s.toString().padStart(2, '0')}`
