const scene = new THREE.Scene()
scene.background = new THREE.Color(0x07060e)
scene.fog = new THREE.FogExp2(0x07060e, 0.018)

const camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.1, 160)
camera.position.set(0, 24, 20)

const world = {
  rig: new CameraRig(camera),
  pulse: 0,
  syzygy: 0,
