scene.add(new THREE.AmbientLight(0x2a2440, 0.7))
const hemi = new THREE.HemisphereLight(0x6a70a0, 0x1a1018, 0.55)
scene.add(hemi)
const key = new THREE.DirectionalLight(0xffe6c0, 0.55)
key.position.set(8, 18, 6)
scene.add(key)

const floorUniforms = {
  uTime: { value: 0 },
  uPulse: { value: 0 },
  uSyzygy: { value: 0 },
  uPlayer: { value: new THREE.Vector2() },
}
const floor = new THREE.Mesh(
  new THREE.CircleGeometry(18.4, 80),
  new THREE.ShaderMaterial({
