      uniform vec2 uPlayer;
      varying vec3 vPos;
      void main() {
        float r = length(vPos.xz);
        float a = atan(vPos.z, vPos.x);
        float ring = abs(fract(r * 0.17 - uTime * 0.035) - 0.5);
        float lines = smoothstep(0.07, 0.02, ring);
        float spokes = abs(fract((a / 3.14159265) * 8.0) - 0.5);
        float spoke = smoothstep(0.065, 0.018, spokes) * smoothstep(18.0, 2.0, r);
