        float rim = smoothstep(17.9, 16.5, r) * smoothstep(18.5, 17.5, r);
        vec3 gold = vec3(0.82, 0.58, 0.24);
        vec3 ice = vec3(0.45, 0.78, 1.0);
        vec3 voidc = vec3(0.035, 0.028, 0.06);
        vec3 col = voidc + mix(gold, ice, uSyzygy * 0.65) * (lines * 0.13 + spoke * 0.05 + glow + rim * 0.75);
        float d = length(vPos.xz - uPlayer);
        col += vec3(1.0, 0.93, 0.72) * exp(-d * 1.35) * 0.18;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  }),
)
floor.rotation.x = -Math.PI / 2
scene.add(floor)

