  const ph = Math.acos(2 * Math.random() - 1)
  starPos[i * 3] = r * Math.sin(ph) * Math.cos(th)
  starPos[i * 3 + 1] = r * Math.cos(ph) * 0.6 + 8
  starPos[i * 3 + 2] = r * Math.sin(ph) * Math.sin(th)
  const c = new THREE.Color().setHSL(0.08 + Math.random() * 0.12, 0.25, 0.6 + Math.random() * 0.4)
  starCol[i * 3] = c.r
  starCol[i * 3 + 1] = c.g
  starCol[i * 3 + 2] = c.b
}
