const fx = new Particles(scene, 520)
const audio = new AudioBus()
const ui = new UI()
const game = new Game({ scene, fx, audio, ui, canvas, camera, world })

let meta = loadMeta()
game.setMeta(meta)
game.startDemo()
ui.setTitle(meta)

const keys = new Set()
const input = {
  x: 0,
  z: 0,
  aimx: 1,
  aimz: 0,
  dash: false,
  fling: false,
  pulse: false,
  attract: false,
  reverse: false,
  selDelta: 0,
}
const mouse = new THREE.Vector2()
const ray = new THREE.Raycaster()
const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0)
const hit = new THREE.Vector3()

function bind() {
  window.addEventListener('keydown', (e) => {
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault()
    keys.add(e.code)
    audio.resume()
    if (e.code === 'Escape') togglePause()
    if (e.code === 'KeyR') input.reverse = true
    if (e.code === 'Space') input.dash = true
    if (e.code === 'KeyF') input.pulse = true
  })
  window.addEventListener('keyup', (e) => keys.delete(e.code))
  window.addEventListener('pointerdown', (e) => {
    audio.resume()
    if (e.button === 0) input.fling = true
    if (e.button === 2) input.pulse = true
  })
  window.addEventListener('pointermove', (e) => {
    mouse.x = (e.clientX / window.innerWidth) * 2 - 1
    mouse.y = -(e.clientY / window.innerHeight) * 2 + 1
  })
  window.addEventListener('contextmenu', (e) => e.preventDefault())
  window.addEventListener('wheel', (e) => {
    input.selDelta += e.deltaY > 0 ? 1 : -1
  }, { passive: true })

  document.getElementById('btn-embark').onclick = embark
  document.getElementById('btn-how').onclick = () => ui.showHow(true)
  document.getElementById('how-close').onclick = () => {
    ui.showHow(false)
    meta.seenHow = true
    saveMeta(meta)
  }
  document.getElementById('btn-reliquary').onclick = openReliquary
  document.getElementById('btn-resume').onclick = () => {
    if (game.mode === 'pause') {
      game.mode = 'play'
      ui.showPause(false)
    }
  }
  document.getElementById('btn-abandon').onclick = () => {
    game.mode = 'title'
    ui.showPause(false)
    game.startDemo()
    ui.setTitle(meta)
  }
  document.getElementById('btn-again').onclick = embark
  document.getElementById('btn-menu').onclick = () => {
    game.mode = 'title'
    game.startDemo()
    ui.setTitle(meta)
  }
  document.getElementById('vol').addEventListener('input', (e) => {
    audio.setVolume(Number(e.target.value) / 100)
  })
}

function embark() {
  audio.resume()
  applyResultIfAny()
  game.setMeta(meta)
  game.startRun()
  if (!meta.seenHow) ui.hint('Line two relics through your core, then pulse or fling')
}

function openReliquary() {
  applyResultIfAny()
  ui.showReliquary(
    meta,
    (u) => {
      if (meta.unlocks[u.id] || meta.ash < u.cost) return
      meta.ash -= u.cost
      meta.unlocks[u.id] = true
      saveMeta(meta)
      audio.relic()
      openReliquary()
    },
    () => {
      ui.show(ui.els.reliquary, false)
      ui.setTitle(meta)
    },
  )
}

function applyResultIfAny() {
  const r = game.lastResult
  if (!r) return
  meta.ash += r.ash
  meta.runs += 1
  if (r.win) meta.wins += 1
  const score = r.kills + r.floor * 20 + (r.win ? 100 : 0)
  if (score > meta.best) meta.best = score
  saveMeta(meta)
  game.lastResult = null
}

function togglePause() {
  if (game.mode === 'play') {
    game.mode = 'pause'
    ui.showPause(true)
  } else if (game.mode === 'pause') {
    game.mode = 'play'
    ui.showPause(false)
  }
}

function pollInput() {
  let x = 0
  let z = 0
  if (keys.has('KeyA') || keys.has('ArrowLeft')) x -= 1
  if (keys.has('KeyD') || keys.has('ArrowRight')) x += 1
  if (keys.has('KeyW') || keys.has('ArrowUp')) z -= 1
  if (keys.has('KeyS') || keys.has('ArrowDown')) z += 1
  input.x = x
  input.z = z
  input.attract = keys.has('ShiftLeft') || keys.has('ShiftRight')

  ray.setFromCamera(mouse, camera)
  if (ray.ray.intersectPlane(plane, hit)) {
    const dx = hit.x - game.player.x
    const dz = hit.z - game.player.z
    const m = Math.hypot(dx, dz)
    if (m > 0.05) {
      input.aimx = dx / m
      input.aimz = dz / m
    }
  } else if (x || z) {
    const m = Math.hypot(x, z)
    input.aimx = x / m
    input.aimz = z / m
  }
}

function onResize() {
  const w = window.innerWidth
  const h = window.innerHeight
  renderer.setSize(w, h, false)
  camera.aspect = w / h
  camera.updateProjectionMatrix()
}

window.addEventListener('resize', onResize)

const clock = new THREE.Clock()
let hudT = 0

function frame() {
  const dt = Math.min(0.033, clock.getDelta())
  pollInput()
  game.update(dt, input)
  input.dash = false
  input.fling = false
  input.pulse = false
  input.reverse = false
  input.selDelta = 0

  world.pulse = Math.max(0, world.pulse - dt * 1.8)
  world.syzygy = Math.max(0, world.syzygy - dt * 1.4)
  floorUniforms.uTime.value += dt
  floorUniforms.uPulse.value = world.pulse
  floorUniforms.uSyzygy.value = world.syzygy
  floorUniforms.uPlayer.value.set(game.player.x, game.player.z)
  stars.rotation.y += dt * 0.012
  fx.update(dt)
  world.rig.update(dt, game.player, game.mode !== 'title')
  audio.setTension(game.mode === 'play' ? Math.min(1, game.enemies.length / 10 + game.floor * 0.2) : 0.15)

  hudT += dt
  if (hudT > 0.08 && (game.mode === 'play' || game.mode === 'cards' || game.mode === 'altar' || game.mode === 'pause')) {
    ui.renderRun(game)
    hudT = 0
  }

  renderer.render(scene, camera)
  requestAnimationFrame(frame)
}

bind()
onResize()
requestAnimationFrame(frame)
