      ui.show(ui.els.reliquary, false)
      ui.setTitle(meta)
    },
  )
}

function applyResultIfAny() {
  const r = game.lastResult
  if (!r) return
  meta.ash += r.ash
  meta.runs += 1
  if (r.win) meta.wins += 1
  const score = r.kills + r.floor * 20 + (r.win ? 100 : 0)
  if (score > meta.best) meta.best = score
  saveMeta(meta)
  game.lastResult = null
}

function togglePause() {
  if (game.mode === 'play') {
    game.mode = 'pause'
    ui.showPause(true)
  } else if (game.mode === 'pause') {
    game.mode = 'play'
    ui.showPause(false)
  }
}

function pollInput() {
  let x = 0
  let z = 0
  if (keys.has('KeyA') || keys.has('ArrowLeft')) x -= 1
  if (keys.has('KeyD') || keys.has('ArrowRight')) x += 1
  if (keys.has('KeyW') || keys.has('ArrowUp')) z -= 1
  if (keys.has('KeyS') || keys.has('ArrowDown')) z += 1
  input.x = x
  input.z = z
  input.attract = keys.has('ShiftLeft') || keys.has('ShiftRight')

  ray.setFromCamera(mouse, camera)
  if (ray.ray.intersectPlane(plane, hit)) {
    const dx = hit.x - game.player.x
    const dz = hit.z - game.player.z
    const m = Math.hypot(dx, dz)
    if (m > 0.05) {
      input.aimx = dx / m
      input.aimz = dz / m
    }
  } else if (x || z) {
    const m = Math.hypot(x, z)
    input.aimx = x / m
    input.aimz = z / m
  }
}

function onResize() {
  const w = window.innerWidth
  const h = window.innerHeight
  renderer.setSize(w, h, false)
  camera.aspect = w / h
  camera.updateProjectionMatrix()
}

window.addEventListener('resize', onResize)

const clock = new THREE.Clock()
let hudT = 0

function frame() {
  const dt = Math.min(0.033, clock.getDelta())
  pollInput()
  game.update(dt, input)
  input.dash = false
  input.fling = false
  input.pulse = false
  input.reverse = false
  input.selDelta = 0

  world.pulse = Math.max(0, world.pulse - dt * 1.8)
  world.syzygy = Math.max(0, world.syzygy - dt * 1.4)
  floorUniforms.uTime.value += dt
  floorUniforms.uPulse.value = world.pulse
  floorUniforms.uSyzygy.value = world.syzygy
  floorUniforms.uPlayer.value.set(game.player.x, game.player.z)
  stars.rotation.y += dt * 0.012
  fx.update(dt)
  world.rig.update(dt, game.player, game.mode !== 'title')
  audio.setTension(game.mode === 'play' ? Math.min(1, game.enemies.length / 10 + game.floor * 0.2) : 0.15)

  hudT += dt
  if (hudT > 0.08 && (game.mode === 'play' || game.mode === 'cards' || game.mode === 'altar' || game.mode === 'pause')) {
    ui.renderRun(game)
    hudT = 0
  }

  renderer.render(scene, camera)
  requestAnimationFrame(frame)
}

bind()
onResize()
requestAnimationFrame(frame)
