{"type":"tool_call","toolCallId":"call-bde3029a-e04e-451e-89cd-65e4ddca5f0b-32","title":"search_replace","kind":"edit","status":"pending","toolName":"search_replace","rawInput":{"file_path":"/private/var/folders/_l/4gzjzznn2z73r8kldgtyxsmw0000gn/T/jonny-bench-work-MDvKkH/scripts/verify.mjs","old_string":"","new_string":"import puppeteer from 'puppeteer-core'
import { writeFileSync, mkdirSync } from 'node:fs'
import { resolve } from 'node:path'

const url = process.argv[2] || 'http://127.0.0.1:5173/'
const outDir = resolve('scripts/shots')
mkdirSync(outDir, { recursive: true })

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: 'new',
  args: [
    '--use-angle=metal',
    '--enable-webgl',
    '--ignore-gpu-blocklist',
    '--window-size=1440,900',
    '--no-sandbox',
  ],
  defaultViewport: { width: 1440, height: 900 },
})

const page = await browser.newPage()
const errors = []
page.on('pageerror', (err) => errors.push(String(err)))
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text())
})

await page.goto(url, { waitUntil: 'networkidle0', timeout: 30000 })
await page.waitForSelector('h1')
await new Promise((r) => setTimeout(r, 800))
await page.screenshot({ path: resolve(outDir, 'title.png') })

const title = await page.$eval('h1', (el) => el.textContent)
const embark = await page.$('#btn-embark')
if (!embark) throw new Error('Embark button missing')

await embark.click()
await new Promise((r) => setTimeout(r, 900))
const hudHidden = await page.$eval('#hud', (el) => el.classList.contains('hidden'))
await page.screenshot({ path: resolve(outDir, 'play.png') })

// mash some inputs
await page.mouse.move(900, 400)
await page.keyboard.down('KeyD')
await page.keyboard.down('KeyW')
for (let i = 0; i < 8; i++) {
  await page.keyboard.press('Space')
  await page.mouse.click(980, 420)
  await page.mouse.click(980, 420, { button: 'right' })
  await page.keyboard.press('KeyR')
  await new Promise((r) => setTimeout(r, 180))
}
await page.keyboard.up('KeyD')
await page.keyboard.up('KeyW')
await page.screenshot({ path: resolve(outDir, 'action.png') })

const hudText = await page.evaluate(() => ({
  floor: document.getElementById('hud-floor')?.textContent,
  chamber: document.getElementById('hud-chamber')?.textContent,
  pips: document.querySelectorAll('#integrity .pip').length,
  orbs: document.querySelectorAll('#orrery .orb-slot').length,
}))

await browser.close()

const report = { url, title, hudHidden, hudText, errors }
writeFileSync(resolve(outDir, 'report.json'), JSON.stringify(report, null, 2))
console.log(JSON.stringify(report, null, 2))
if (errors.length) process.exit(1)
