{"type":"tool_call","toolCallId":"call-4369136f-7ef0-4092-ad45-898d4285970f-51","title":"write","kind":"write","status":"pending","toolName":"write","rawInput":{"file_path":"/private/var/folders/_l/4gzjzznn2z73r8kldgtyxsmw0000gn/T/jonny-bench-work-MDvKkH/scripts/verify.mjs","content":"import puppeteer from 'puppeteer-core'
import { writeFileSync, mkdirSync } from 'node:fs'
import { resolve } from 'node:path'

const url = process.argv[2] || 'http://127.0.0.1:5173/'
const outDir = resolve('scripts/shots')
mkdirSync(outDir, { recursive: true })

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: 'new',
  args: [
    '--use-angle=metal',
    '--enable-webgl',
    '--ignore-gpu-blocklist',
    '--window-size=1440,900',
    '--no-sandbox',
  ],
  defaultViewport: { width: 1440, height: 900 },
})

const page = await browser.newPage()
const errors = []
page.on('pageerror', (err) => errors.push(String(err)))
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text())
})

const wait = (ms) => new Promise((r) => setTimeout(r, ms))

await page.goto(url, { waitUntil: 'networkidle0', timeout: 30000 })
await page.waitForSelector('h1')
await wait(700)
await page.screenshot({ path: resolve(outDir, 'title.png') })

await page.click('#btn-how')
await wait(250)
const howOpen = await page.$eval('#how', (el) => !el.classList.contains('hidden'))
await page.screenshot({ path: resolve(outDir, 'how.png') })
await page.click('#how-close')

await page.click('#btn-reliquary')
await wait(250)
const relOpen = await page.$eval('#reliquary', (el) => !el.classList.contains('hidden'))
const unlocks = await page.$$eval('#unlock-grid .unlock-item', (els) => els.length)
await page.screenshot({ path: resolve(outDir, 'reliquary.png') })
await page.click('#reliquary-close')

await page.click('#btn-embark')
await wait(900)
const play = await page.evaluate(() => {
  const g = window.__syzygy
  return {
    mode: g.mode,
    enemies: g.enemies.length,
    orbiters: g.orbiters.map((o) => o.id),
    hp: g.player.hp,
    hudHidden: document.getElementById('hud').classList.contains('hidden'),
    chamber: document.getElementById('hud-chamber')?.textContent,
  }
})
await page.screenshot({ path: resolve(outDir, 'play.png') })

await page.mouse.move(980, 420)
await page.keyboard.down('KeyD')
await page.keyboard.down('KeyW')
for (let i = 0; i < 6; i++) {
  await page.keyboard.press('Space')
  await page.mouse.click(1000, 400)
  await page.mouse.click(1000, 400, { button: 'right' })
  await page.keyboard.press('KeyR')
  await wait(160)
}
await page.keyboard.up('KeyD')
await page.keyboard.up('KeyW')
await page.screenshot({ path: resolve(outDir, 'action.png') })

await page.evaluate(() => {
  const g = window.__syzygy
  for (const e of g.enemies) e.hp = 0
})
await wait(1100)
const cards = await page.evaluate(() => ({
  mode: window.__syzygy.mode,
  visible: !document.getElementById('cards').classList.contains('hidden'),
  count: document.querySelectorAll('#card-row .card').length,
}))
await page.screenshot({ path: resolve(outDir, 'cards.png') })

if (cards.visible) {
  await page.click('#card-row .card')
  await wait(700)
}
const afterCard = await page.evaluate(() => ({
  mode: window.__syzygy.mode,
  chamber: document.getElementById('hud-chamber')?.textContent,
  room: window.__syzygy.roomIndex,
  taken: window.__syzygy.taken,
}))
await page.screenshot({ path: resolve(outDir, 'chamber2.png') })

await page.keyboard.press('Escape')
await wait(200)
const paused = await page.evaluate(() => ({
  mode: window.__syzygy.mode,
  visible: !document.getElementById('pause').classList.contains('hidden'),
}))
await page.screenshot({ path: resolve(outDir, 'pause.png') })
await page.click('#btn-resume')
await wait(150)

await page.evaluate(() => window.__syzygy.die())
await wait(400)
const results = await page.evaluate(() => ({
  mode: window.__syzygy.mode,
  visible: !document.getElementById('results').classList.contains('hidden'),
  title: document.getElementById('results-title')?.textContent,
}))
await page.screenshot({ path: resolve(outDir, 'results.png') })

await browser.close()

const report = { url, howOpen, relOpen, unlocks, play, cards, afterCard, paused, results, errors }
writeFileSync(resolve(outDir, 'report.json'), JSON.stringify(report, null, 2))
console.log(JSON.stringify(report, null, 2))
if (errors.length) process.exit(1)
if (!howOpen || !relOpen || !play.enemies || !cards.visible || !results.visible) process.exit(2)
