  return null;
});
await new Promise(r => setTimeout(r, 200));
const afterAltar = await p.evaluate(() => {
  const g = window.__syzygy;
  g.roomIndex = 5;
  g.beginRoom();
  return {
    mode: g.mode,
    kind: g.roomKind,
    boss: g.boss && (g.boss.name || g.boss.title),
    bar: !document.getElementById('boss-bar').classList.contains('hidden'),
    enemies: g.enemies.length,
  };
});
await new Promise(r => setTimeout(r, 400));
await p.screenshot({ path: 'scripts/shots/boss.png' });
console.log(JSON.stringify({ altar, afterAltar, errs }, null, 2));
await b.close();
