import puppeteer from 'puppeteer-core';
const b = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: 'new',
  args: ['--use-angle=metal','--enable-webgl','--no-sandbox'],
  defaultViewport: { width: 1440, height: 900 },
});
const p = await b.newPage();
const errs = [];
p.on('pageerror', e => errs.push(String(e)));
await p.goto('http://127.0.0.1:4177/benches/syzygy/runs/demo/app/', { waitUntil: 'networkidle0' });
await new Promise(r => setTimeout(r, 400));
await p.click('#btn-embark');
await new Promise(r => setTimeout(r, 600));
const altar = await p.evaluate(() => {
  const g = window.__syzygy;
  g.stardust = 80;
  g.roomIndex = 3;
  g.beginRoom();
  return { mode: g.mode, enemies: g.enemies.length, items: document.querySelectorAll('#altar-grid .shop-item').length };
});
await new Promise(r => setTimeout(r, 500));
await p.screenshot({ path: 'scripts/shots/altar2.png' });
const afterIdle = await p.evaluate(() => ({ mode: window.__syzygy.mode, enemies: window.__syzygy.enemies.length }));
await p.evaluate(() => {
  const g = window.__syzygy;
  g.roomIndex = 5;
  g.beginRoom();
});
await new Promise(r => setTimeout(r, 700));
const boss = await p.evaluate(() => {
  const g = window.__syzygy;
  const e = g.enemies[0];
  return {
    mode: g.mode,
    kind: g.roomKind,
    enemies: g.enemies.length,
    name: e && e.name,
    bossId: e && e.boss,
    bar: !document.getElementById('boss-bar').classList.contains('hidden'),
    barName: document.getElementById('boss-name')?.textContent,
  };
});
await p.screenshot({ path: 'scripts/shots/boss2.png' });
console.log(JSON.stringify({ altar, afterIdle, boss, errs }, null, 2));
await b.close();
